#!/usr/bin/env python3
from pathlib import Path
import sys,shutil,datetime,os
CHANGES = {'static/app.js': [('function compactChecks(id,title){const box=$(id);if(!box)return;', "function compactChecks(id,title){const box=$(id);if(!box)return;\n /* FSJ_CALL_SELECTION_STABLE_V1 */\n if(id==='callParticipants'){\n  const previous=box.previousElementSibling;if(previous?.classList.contains('compact-checks'))previous.remove();\n  box.classList.remove('original-checks');box.setAttribute('aria-label','Convidar até três participantes');\n  box.querySelectorAll('label').forEach(label=>{label.style.cssText='display:flex;align-items:center;gap:8px;margin:3px 0;min-height:36px';const input=label.querySelector('input');if(input)input.style.cssText='width:20px;height:20px;margin:0;flex:0 0 20px';});return;\n }\n")], 'static/calls.js': [("$('callParticipants').addEventListener('change',()=>saveDraft());", "$('callParticipants').addEventListener('change',e=>{if(document.querySelectorAll('[name=callParticipant]:checked').length>3){e.target.checked=false;say('Selecione até três convidados.');}saveDraft();});"), ("async function session(u){const generation=++sessionGeneration;if(!u||user&&user.id!==u.id){recorded=null;chunks=[];$('recordSave').hidden=true;}if(!user||user.id!==u?.id)lastListSignature='';user=u;if(!u){await leave(false);return;}$('callCreate').hidden=u.role!=='owner';if(u.role==='owner'){try{const selected=[...document.querySelectorAll('[name=callParticipant]:checked')].map(x=>x.value),draft=readDraft();if(draft&&typeof draft.title==='string')$('callNewTitle').value=draft.title;if(draft?.mode)$('callMode').value=draft.mode;const users=(await fetch('/api/users').then(r=>r.json())).users||[],directory=window.fsjMirrorData?.directory||[],roster=(()=>{const active=users.filter(p=>p.status==='active'&&p.id!==u.id),linked=directory.filter(p=>p.active&&p.user_id&&active.some(a=>a.id===p.user_id));return [...linked.map(p=>({id:'p:'+p.person_id,name:p.name})),...active.filter(p=>!linked.some(a=>a.user_id===p.id)).map(p=>({id:p.id,name:p.display_name||p.name}))];})();if(generation!==sessionGeneration)return;const signature=JSON.stringify(roster),liveSelected=[...document.querySelectorAll('[name=callParticipant]:checked')].map(x=>x.value);if($('callParticipants').dataset.roster!==signature){$('callParticipants').dataset.roster=signature;$('callParticipants').replaceChildren(...roster.map(p=>{const label=document.createElement('label');label.className='check';const input=document.createElement('input');input.type='checkbox';input.name='callParticipant';input.value=p.id;input.checked=(liveSelected.length?liveSelected:selected.length?selected:draft?.participants||[]).includes(p.id);label.append(input,document.createTextNode(p.name));return label;}));}}catch{say('Não foi possível carregar os participantes.');}}document.dispatchEvent(new Event('fsj:call-participants'));await listCalls();}", "let participantOwner='';\nasync function session(u){\n const generation=++sessionGeneration;\n if(!u||user&&user.id!==u.id){recorded=null;chunks=[];$('recordSave').hidden=true;}\n if(!user||user.id!==u?.id)lastListSignature='';user=u;\n if(!u){participantOwner='';$('callParticipants').replaceChildren();delete $('callParticipants').dataset.roster;await leave(false);return;}\n $('callCreate').hidden=u.role!=='owner';\n if(u.role==='owner')try{\n  const first=participantOwner!==u.id,draft=first?readDraft():null;\n  if(first){$('callParticipants').replaceChildren();delete $('callParticipants').dataset.roster;}\n  if(first&&typeof draft?.title==='string')$('callNewTitle').value=draft.title;\n  if(first&&draft?.mode)$('callMode').value=draft.mode;\n  const response=await fetch('/api/users');if(!response.ok)throw Error('Participantes indisponíveis.');\n  const users=(await response.json()).users||[];if(generation!==sessionGeneration)return;\n  const directory=window.fsjMirrorData?.directory||[];\n  const canonical=id=>id.startsWith('p:')?(directory.find(p=>'p:'+p.person_id===id)?.user_id||id):id;\n  const chosen=new Set((first?(draft?.participants||[]):[...document.querySelectorAll('[name=callParticipant]:checked')].map(x=>x.dataset.uid||x.value)).map(canonical));\n  const roster=users.filter(p=>p.status==='active'&&p.id!==u.id).map(p=>{const linked=directory.find(d=>d.active&&d.user_id===p.id);return {id:linked?'p:'+linked.person_id:p.id,uid:p.id,name:linked?.name||p.display_name||p.name};});\n  const signature=JSON.stringify(roster);\n  if($('callParticipants').dataset.roster!==signature){\n   $('callParticipants').dataset.roster=signature;\n   $('callParticipants').replaceChildren(...roster.map(p=>{const label=document.createElement('label');label.className='check';const input=document.createElement('input');input.type='checkbox';input.name='callParticipant';input.value=p.id;input.dataset.uid=p.uid;input.checked=chosen.has(p.uid);label.append(input,document.createTextNode(p.name));return label;}));\n  }\n  participantOwner=u.id;saveDraft();\n }catch{say('Não foi possível carregar os participantes.');}\n document.dispatchEvent(new Event('fsj:call-participants'));await listCalls();\n}")]}
base=Path(sys.argv[1]).resolve()
prepared={}
for name,pairs in CHANGES.items():
 p=base/name;text=p.read_text()
 if name=='static/app.js' and 'FSJ_CALL_SELECTION_STABLE_V1' in text: continue
 if name=='static/calls.js' and "let participantOwner='';" in text: continue
 for old,new in pairs:
  if text.count(old)!=1: raise SystemExit('Arquivo diferente do esperado: '+name+'. Nada alterado.')
  text=text.replace(old,new,1)
 prepared[p]=text
if not prepared: print('Correção já instalada.');sys.exit()
backup=base/'backups'/('selecao-chamada-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f'))
backup.mkdir(parents=True)
try:
 for p,text in prepared.items():
  target=backup/p.relative_to(base);target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,target)
 for p,text in prepared.items():
  temp=p.with_name(p.name+'.selecao.tmp');temp.write_text(text);shutil.copymode(p,temp);os.replace(temp,p)
except Exception:
 for p in prepared:
  saved=backup/p.relative_to(base)
  if saved.exists():shutil.copy2(saved,p)
 raise
print('INSTALADO: convidados com caixas de seleção visíveis e identificação estável.')
print('Backup:',backup)
print('Feche e reabra o Reserva. Não é necessário reinstalar o Android nem reiniciar a VM.')
print('Contas, senhas, recuperação WhatsApp e rotina das 7h preservadas. Nenhuma chamada iniciada.')
